for (const [french, english] of auditedFrenchFirst) {
  frenchToEnglish[french] = english;
  englishToFrench[english] = french;
  // Some older entries in sharedCopy were stored in English-first order.
  // Preserve English labels when English is active, while keeping their
  // canonical French translation for the French locale.
  frenchToEnglish[english] = english;
}
// API transaction statuses are lower-case codes, so map those separately from
// their sentence-case UI labels above.
englishToFrench.completed = "Terminé";
englishToFrench.pending = "En attente";
englishToFrench.failed = "Échoué";
frenchToEnglish.completed = "completed";
frenchToEnglish.pending = "pending";
frenchToEnglish.failed = "failed";

export function translateText(text: string, language: AppLanguage): string {
  const content = text.trim();
  // Keep whitespace-only React Native text nodes intact. They often carry
  // deliberate line breaks inside headings, and splitting leading/trailing
  // whitespace would otherwise duplicate those breaks.
  if (!content) return text;
  const dynamicTranslations: Array<[RegExp, string]> = language === "en"
    ? [
        [/^ID de transaction copié:\s*(.+)$/i, "Transaction ID copied: $1"],
        [/^Les transferts Mobile Money vers (.+) ne sont pas encore activés\.$/i, "Mobile Money transfers to $1 are not available yet."],
        [/^Envoyer à (.+)$/i, "Send to $1"],
        [/^Tu as reçu ([\d., ]+) ([A-Z]{3}) de (.+) sur ton compte ZENO\.$/i, "You received $1 $2 from $3 in your ZENO account."],
        [/^Recharge démo de (.+) USD effectué\. Aucun argent réel n'a été déplacé\.$/i, "Demo top up of $1 USD completed. No real money was moved."],
        [/^Transfert démo de (.+) USD effectué\. Aucun argent réel n'a été déplacé\.$/i, "Demo transfer of $1 USD completed. No real money was moved."],
        [/^Carte ZENO rechargée\s*:\s*(.+) USD\.$/i, "ZENO Card topped up: $1 USD."],
        [/^Transfert vers le wallet\s*:\s*(.+) USD\.$/i, "Transfer to wallet: $1 USD."],
        [/^Votre nouveau code PIN à (\d+) chiffres a été enregistré\.$/i, "Your new $1-digit PIN has been saved."],
        [/^Devise principale réglée sur (.+)$/, "Primary currency set to $1"],
        [/^(.+) sera utilisée pour la conversion d'affichage\.$/, "$1 will be used for display conversion."],
      ]
    : [
        [/^Transaction ID copied:\s*(.+)$/i, "ID de transaction copié : $1"],
        [/^Mobile Money transfers to (.+) are not available yet\.$/i, "Les transferts Mobile Money vers $1 ne sont pas encore activés."],
        [/^Send to (.+)$/i, "Envoyer à $1"],
        [/^You received ([\d., ]+) ([A-Z]{3}) from (.+) in your ZENO account\.$/i, "Tu as reçu $1 $2 de $3 sur ton compte ZENO."],
        [/^Your current balance is (.+)$/i, "Votre solde actuel est $1"],
        [/^Your new (\d+)-digit PIN has been saved\.$/i, "Votre nouveau code PIN à $1 chiffres a été enregistré."],
        [/^Primary currency set to (.+)$/, "Devise principale réglée sur $1"],
        [/^(.+) will be used for display conversion\.$/, "$1 sera utilisée pour la conversion d'affichage."],
      ];
  for (const [pattern, replacement] of dynamicTranslations) {
    if (pattern.test(content)) {
      return text.replace(content, content.replace(pattern, replacement));
    }
  }
  const dictionary = language === "en" ? frenchToEnglish : englishToFrench;
  const leading = text.match(/^\s*/)?.[0] ?? "";
  const trailing = text.match(/\s*$/)?.[0] ?? "";
  return `${leading}${dictionary[content] ?? content}${trailing}`;
}
